const sumSpentInWindow = `-- name: SumSpentInWindow :one
SELECT COALESCE(SUM(
    CASE
        WHEN transaction_type = 'withdrawal' THEN -amount
        WHEN transaction_type = 'hold' AND status = 'captured' THEN -amount
        WHEN transaction_type = 'hold' AND status = 'active' THEN COALESCE(authorized_amount, 0)
        ELSE 0
    END), 0)::bigint
FROM billing.credit_transactions
WHERE tenant_id = $1 AND tenant_subject_id = $2 AND credit_type_id = $3
  AND created_at >= $4::timestamptz
  AND ($5::text = '' OR actor = $5::text)
`

type SumSpentInWindowParams struct {
	TenantID        uuid.UUID
	TenantSubjectID uuid.UUID
	CreditTypeID    uuid.UUID
	Since           time.Time
	Actor           string
}

// Spend counted against a rate cap since `since`: settled spend (withdrawals +
// captured holds) PLUS currently-active holds created in the window, so
// concurrent in-flight holds can't overshoot a cap. Empty actor = all actors.
func (q *Queries) SumSpentInWindow(ctx context.Context, arg SumSpentInWindowParams) (int64, error) {
	row := q.db.QueryRow(ctx, sumSpentInWindow,
		arg.TenantID,
		arg.TenantSubjectID,
		arg.CreditTypeID,
		arg.Since,
		arg.Actor,
	)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

